fn cut_word(w: Str, width: Int) -> List[Str] {
  var pieces: List[Str] = []
  var i = 0
  while i < w.len() {
    let stop = (i + width).min(w.len())
    pieces = pieces.push(w.slice(i, stop))
    i = i + width
  }
  return pieces
}

pub fn wrap(text: Str, width: Int) -> List[Str] {
  var lines: List[Str] = []
  var cur = ""
  for word in text.split(" ") {
    if word != "" {
      for piece in cut_word(word, width) {
        if cur == "" {
          cur = piece
        } else if cur.len() + 1 + piece.len() <= width {
          cur = cur + " " + piece
        } else {
          lines = lines.push(cur)
          cur = piece
        }
      }
    }
  }
  if cur != "" {
    lines = lines.push(cur)
  }
  return lines
}
